class Solution {
    public String orderlyQueue(String s,int k){
        if(k>1){
            char[] chars=s.toCharArray();
            Arrays.sort(chars);
            return new String(chars);
        }
        String best=s;
        for(int shift=1;shift<s.length();shift++){
            String candidate=s.substring(shift)+s.substring(0,shift);
            if(candidate.compareTo(best)<0)best=candidate;
        }
        return best;
    }
}

code.kotlin:
class Solution {
    fun orderlyQueue(s:String,k:Int):String{
        if(k>1)return s.toCharArray().sorted().joinToString("");
        var best=s;
        for(shift in 1 until s.length){
            val candidate=s.substring(shift)+s.substring(0,shift);
            if(candidate<best)best=candidate
        };
        return best
    }
}

code.cpp:
class Solution {
    public: string orderlyQueue(string s,int k){
        if(k>1){
            sort(s.begin(),s.end());
            return s;
        }
        string best=s;
        for(int shift=1;shift<(int)s.size();++shift){
            string candidate=s.substr(shift)+s.substr(0,shift);
            best=min(best,candidate);
        }
        return best;
    }
};
